#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *shift_str = argv[1];
    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > 1024) {
        puts("USAGE");
        return 0;
    }
    long shift_long = strtol(shift_str, NULL, 10);
    int shift = (int)(shift_long % 26);
    if (shift < 0) shift += 26;
    for (size_t i = 0; i < len; ++i) {
        char c = text[i];
        if (c >= 'A' && c <= 'Z') {
            c = (char)('A' + (c - 'A' + shift) % 26);
        } else if (c >= 'a' && c <= 'z') {
            c = (char)('a' + (c - 'a' + shift) % 26);
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
